create table public.floor_plan_share_tokens (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, user_id uuid not null references auth.users(id), kind text not null check(kind in ('ceremony','reception')), token text not null unique default encode(extensions.gen_random_bytes(32),'hex'), permission text not null default 'view_only' check(permission in ('view_only','can_edit')), recipient_name text, created_at timestamptz not null default now(), expires_at timestamptz not null default now()+interval '90 days', last_accessed_at timestamptz); alter table public.floor_plan_share_tokens enable row level security; grant select,insert,update,delete on public.floor_plan_share_tokens to authenticated; grant all on public.floor_plan_share_tokens to service_role; create policy owner_access on public.floor_plan_share_tokens for all to authenticated using (user_id=auth.uid() and exists(select 1 from public.events e where e.id=floor_plan_share_tokens.event_id and e.user_id::text=auth.uid()::text)) with check(user_id=auth.uid() and exists(select 1 from public.events e where e.id=floor_plan_share_tokens.event_id and e.user_id::text=auth.uid()::text)); create index floor_plan_share_event on public.floor_plan_share_tokens(event_id,kind);
